<script setup>
import {onMounted,computed,ref} from 'vue';import{api}from'../services/api'
const detail=ref(null),providers=ref([]),selected=ref(''),status=ref(''),busy=ref(false);const units=computed(()=>detail.value?.structure?.units||[])
async function load(){detail.value=await api.projectDetail();providers.value=(await api.providerStatus()).providers||[];selected.value=units.value[0]?.id||''}async function generate(){busy.value=true;status.value='Generando propuesta y extrayendo imágenes…';try{status.value=(await api.generate({unit_id:selected.value,provider:'ollama'})).message||'Propuesta en cola.'}catch(e){status.value=e.message}finally{busy.value=false}}async function validate(){try{const r=await api.validate(selected.value);status.value=r.status==='pass'?'DTBook válido para auditoría humana.':(r.errors||[]).join(' · ')||'Pendiente'}catch(e){status.value=e.message}}onMounted(load)
</script>
<template><section class="hero"><span class="eyebrow">PASO 1 · LECCIONES</span><h2>Generar y auditar DTBook</h2><p>Selecciona una unidad, genera su propuesta y valida el resultado.</p></section><section class="library-card lesson-controls"><label>Unidad activa<select v-model="selected"><option v-for="unit in units" :key="unit.id" :value="unit.id">{{unit.name||unit.file}}</option></select></label><span class="hint">Proveedores: {{providers.filter(p=>p.available).map(p=>p.label).join(', ')||'consultando…'}}</span><div class="button-row"><button :disabled="busy||!selected" @click="generate">{{busy?'Generando…':'Generar propuesta'}}</button><button class="secondary" :disabled="!selected" @click="validate">Validar DTBook</button></div><p v-if="status" class="notice">{{status}}</p></section></template>
